public class Employee {
    // 1. Immutable ID and private fields
    private final String employeeId;
    private String name;
    private String department;
    private double monthlySalary;
    private int performanceRating;

    // 2. Parameterized constructor with validation
    public Employee(String employeeId, String name, String department, double monthlySalary) {
        if (employeeId == null || employeeId.trim().isEmpty()) {
            throw new IllegalArgumentException("Employee ID cannot be empty.");
        }
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Name cannot be empty.");
        }
        if (monthlySalary < 1000.0) {
            throw new IllegalArgumentException("Initial monthly salary must be at least $1,000.00.");
        }
        this.employeeId = employeeId.trim();
        this.name = name.trim();
        this.department = (department != null) ? department.trim() : "General";
        this.monthlySalary = monthlySalary;
        this.performanceRating = 3; // Default average rating
    }

    // 3. Regulated raise method
    public boolean giveRaise(double percentage) {
        if (percentage < 0.5 || percentage > 25.0) {
            System.err.printf("Raise rejected: %.1f%% outside policy limits (0.5%% - 25.0%%).%n", percentage);
            return false;
        }
        double increase = this.monthlySalary * (percentage / 100.0);
        this.monthlySalary += increase;
        System.out.printf("Approved: %.1f%% raise granted. New monthly salary: $%.2f%n", percentage, this.monthlySalary);
        return true;
    }

    // 4. Financial projections
    public double calculateAnnualSalary() {
        return this.monthlySalary * 12.0;
    }

    public double calculateAnnualTax(double taxRate) {
        if (taxRate < 0.0 || taxRate > 0.40) {
            throw new IllegalArgumentException("Tax rate must be between 0.0 and 0.40 (40%).");
        }
        return calculateAnnualSalary() * taxRate;
    }

    // 5. Rating mutator
    public void setPerformanceRating(int rating) {
        if (rating < 1 || rating > 5) {
            System.err.println("Performance rating must be between 1 and 5.");
            return;
        }
        this.performanceRating = rating;
    }

    // 6. Report renderer
    public void generateCompensationReport() {
        double annualGross = calculateAnnualSalary();
        double estTax = calculateAnnualTax(0.20); // 20% estimated bracket
        double netPay = annualGross - estTax;

        System.out.println("=======================================================");
        System.out.println("             EMPLOYEE COMPENSATION REPORT              ");
        System.out.println("=======================================================");
        System.out.printf("Employee ID:        %s%n", employeeId);
        System.out.printf("Employee Name:      %s%n", name);
        System.out.printf("Department:         %s%n", department);
        System.out.printf("Performance Rating: %d/5%n", performanceRating);
        System.out.printf("Monthly Salary:     $%.2f%n", monthlySalary);
        System.out.printf("Annual Gross:       $%.2f%n", annualGross);
        System.out.printf("Est. Annual Tax:    $%.2f (at 20.0%%)%n", estTax);
        System.out.printf("Net Take-Home Pay:  $%.2f%n", netPay);
        System.out.println("=======================================================\n");
    }

    // Getters (Notice: NO setEmployeeId or setMonthlySalary)
    public String getEmployeeId() { return employeeId; }
    public String getName() { return name; }
    public String getDepartment() { return department; }
    public double getMonthlySalary() { return monthlySalary; }
    public int getPerformanceRating() { return performanceRating; }
}

